-- ============================================================================
-- MENU MASTER NG
-- Test suite 004: GATE 1 CLOSURE
--
-- Covers migration 0013 (zero-value amounts) and 0014 (sales void-and-reissue).
-- Uses its own results table (_c1) so it never clobbers suite 001 (_test_results)
-- or suite 002 (_g1).
-- ============================================================================

set client_min_messages = warning;

create table if not exists _c1 (
  seq serial primary key, phase text, name text, passed boolean, detail text);
truncate _c1 restart identity;

create or replace function c(p_phase text, p_name text, p_ok boolean, p_detail text default null)
returns void language plpgsql as $$
begin insert into _c1 (phase,name,passed,detail) values (p_phase,p_name,coalesce(p_ok,false),p_detail); end; $$;

-- ============================================================================
-- FIXTURES (independent of suites 001/002)
-- ============================================================================
do $$
declare
  u uuid; onboard jsonb; acc uuid; biz uuid;
  rice uuid; tom uuid; u_kg uuid; u_g uuid;
begin
  insert into auth.users (id,email) values (gen_random_uuid(),'closure@test.local') returning id into u;
  onboard := fn_create_account_and_business('Closure Group','Closure Kitchen','soup_seller', u);
  acc := (onboard->>'account_id')::uuid;  biz := (onboard->>'business_id')::uuid;

  select id into u_kg from units where account_id is null and code='kg';
  select id into u_g  from units where account_id is null and code='g';
  select id into rice from ingredients where account_id=acc and name='Rice (local)';
  select id into tom  from ingredients where account_id=acc and name='Tomato';

  create temp table _cfx as select u, acc, biz, rice, tom, u_kg, u_g;
end $$;

-- ============================================================================
-- A3 / 0013 : ZERO-VALUE AMOUNTS
-- ============================================================================

-- TEST 37: a zero-value purchase line cannot be stored at all
do $$
declare f record; p uuid; ok boolean := false;
begin
  select * into f from _cfx;
  insert into purchases (account_id,business_id,purchase_date,reference)
  values (f.acc,f.biz,current_date,'T37') returning id into p;
  begin
    insert into purchase_lines (account_id,purchase_id,ingredient_id,qty,unit_id,amount)
    values (f.acc,p,f.rice,1,f.u_kg,0);
  exception when check_violation then ok := true;
  end;
  perform c('0013','T37 zero-value purchase line rejected at constraint level', ok);
  delete from purchases where id = p;
end $$;

-- TEST 38: negative still rejected
do $$
