-- TEST 41: the fix is "> 0", not a minimum threshold. A genuinely tiny amount stands.
do $$
declare f record; p uuid; res jsonb; ok boolean;
begin
  select * into f from _cfx;
  insert into purchases (account_id,business_id,purchase_date,reference)
  values (f.acc,f.biz,current_date,'T41') returning id into p;
  insert into purchase_lines (account_id,purchase_id,ingredient_id,qty,unit_id,amount)
  values (f.acc,p,f.rice,1,f.u_kg,0.01);
  res := fn_post_purchase(p);
  ok := (res->>'posted')::boolean;
  perform c('0013','T41 smallest legitimate amount (0.01) still posts', ok, res::text);
end $$;

-- TEST 39: defence in depth. The constraint is the first line; fn_post_purchase
-- is the second. This proves the second line works by removing the first,
-- exercising it, then restoring the constraint. The test row is deleted before
-- the constraint is re-added, so the table is left exactly as it was found.
alter table purchase_lines drop constraint ck_purchase_lines_amount_positive;

do $$
declare f record; p uuid; res jsonb; still_draft boolean; rows_written int;
begin
  select * into f from _cfx;
  insert into purchases (account_id,business_id,purchase_date,reference)
  values (f.acc,f.biz,current_date,'T39') returning id into p;
  insert into purchase_lines (account_id,purchase_id,ingredient_id,qty,unit_id,amount)
  values (f.acc,p,f.tom,1,f.u_kg,0);          -- only possible with the constraint gone

  res := fn_post_purchase(p);
  select status='draft' into still_draft from purchases where id = p;
  select count(*) into rows_written from ingredient_prices where ingredient_id = f.tom;

  perform c('0013','T39 fn_post_purchase refuses a zero-value line (defence in depth)',
    (res->>'posted')::boolean = false
      and res->>'reason' = 'zero_value_lines'
      and still_draft
      and rows_written = 0,
    res::text);

  delete from purchases where id = p;          -- draft, so deletion is permitted
end $$;

alter table purchase_lines add constraint ck_purchase_lines_amount_positive check (amount > 0);

do $$
declare n int;
begin
  select count(*) into n from pg_constraint where conname='ck_purchase_lines_amount_positive';
  perform c('0013','T39b constraint restored after the defence-in-depth test', n = 1);
end $$;

-- ============================================================================
-- A2 / 0014 : SALES VOID-AND-REISSUE AND REVENUE IMMUTABILITY
-- ============================================================================

-- Fixture: a fully priced dish so cost actually freezes at sale.
do $$
declare
  f record; p uuid; rid uuid; ord uuid; ol uuid;
begin
  select * into f from _cfx;

  insert into purchases (account_id,business_id,purchase_date,reference)
  values (f.acc,f.biz,current_date,'A2-BUY') returning id into p;
  insert into purchase_lines (account_id,purchase_id,ingredient_id,qty,unit_id,amount)
  values (f.acc,p,f.rice,10,f.u_kg,50000);        -- 10kg for 50,000 => 5/g
  perform fn_post_purchase(p);

  insert into recipes (account_id,business_id,kind,name,batch_yield_qty,yield_unit_id,
                       cooking_yield_pct,portion_qty,status)
  values (f.acc,f.biz,'dish','A2 Jollof',5000,f.u_g,100,500,'active') returning id into rid;
  insert into recipe_lines (account_id,recipe_id,ingredient_id,qty,unit_id)
  values (f.acc,rid,f.rice,1000,f.u_g);
  perform fn_compute_recipe_cost_snapshot(rid);

  insert into orders (account_id,business_id,order_no,order_date)
  values (f.acc,f.biz,'A2-ORD-1',current_date) returning id into ord;
  insert into order_lines (account_id,order_id,recipe_id,qty,unit_price)
  values (f.acc,ord,rid,2,3500) returning id into ol;

  create temp table _cfx2 as select rid, ord, ol;
end $$;

-- TEST 28 (before finalisation): a draft order is freely editable
do $$
declare g record; ok boolean := true;
begin
  select * into g from _cfx2;
  begin
    update order_lines set unit_price = 3600 where id = g.ol;
    update order_lines set unit_price = 3500 where id = g.ol;   -- put it back
  exception when others then ok := false;
  end;
  perform c('0014','T28 draft order lines remain freely editable', ok);
end $$;

-- Finalise it.
do $$
declare g record; res jsonb;
begin
  select * into g from _cfx2;
  res := fn_finalise_order(g.ord);
  perform c('0014','T23a order finalises', (res->>'finalised')::boolean, res::text);
end $$;

