-- TEST 29: a void needs a reason
do $$
declare g record; ok boolean := false;
begin
  select * into g from _cfx2;
  begin perform fn_void_order(g.ord, '   ');
  exception when others then ok := true; end;
  perform c('0014','T29 void requires a non-empty reason', ok);
end $$;

-- TEST 30 / 33: void removes the money, preserves the record and the frozen cost
do $$
declare
  g record; f record; rev_before numeric; rev_after numeric;
  cost_before numeric; cost_after numeric; still_there boolean; res jsonb;
begin
  select * into f from _cfx; select * into g from _cfx2;
  select revenue into rev_before from v_profit_by_period where business_id = f.biz;
  select unit_cost_at_sale into cost_before from order_lines where id = g.ol;

  res := fn_void_order(g.ord, 'customer returned the order');

  select coalesce(revenue,0) into rev_after from v_profit_by_period where business_id = f.biz;
  select unit_cost_at_sale into cost_after from order_lines where id = g.ol;
  select exists(select 1 from orders where id = g.ord and voided_at is not null) into still_there;

  perform c('0014','T30 voided sale leaves revenue but the record survives',
    coalesce(rev_after,0) < rev_before and still_there,
    format('revenue %s -> %s, row present=%s', rev_before, coalesce(rev_after,0), still_there));

  perform c('0014','T33 voiding does not disturb the frozen unit_cost_at_sale',
    cost_before is not null and cost_before = cost_after,
    format('before=%s after=%s', cost_before, cost_after));

  perform c('0014','T30b voided sale is visible in the audit view',
    exists(select 1 from v_voided_sales where record_id = g.ord
             and void_reason = 'customer returned the order'));
end $$;

-- TEST 31 / 32: reissue carries the link and the corrected sale counts again
do $$
declare
  f record; g record; res jsonb; newid uuid; rev numeric; linked boolean;
begin
  select * into f from _cfx; select * into g from _cfx2;
  res := fn_reissue_order(g.ord);
  newid := (res->>'new_order_id')::uuid;

  select exists(select 1 from orders where id = newid and replaces = g.ord) into linked;
  perform c('0014','T31 reissued order carries replaces -> original', linked, res::text);

  insert into order_lines (account_id,order_id,recipe_id,qty,unit_price)
  values (f.acc,newid,g.rid,1,3500);
  perform fn_finalise_order(newid);

  select revenue into rev from v_profit_by_period where business_id = f.biz;
  perform c('0014','T32 corrected sale counts, voided original does not',
    rev = 3500, format('revenue=%s (expected 3500: 1 x 3500, original 2 x 3500 voided)', rev));
end $$;

-- TEST 36: sales_entries are immutable; correction is void + re-enter
do $$
declare f record; g record; se uuid; ok_u boolean := false; ok_d boolean := false; res jsonb;
begin
  select * into f from _cfx; select * into g from _cfx2;
  insert into sales_entries (account_id,business_id,sale_date,recipe_id,qty,unit_price)
  values (f.acc,f.biz,current_date,g.rid,3,3500) returning id into se;

  begin update sales_entries set unit_price = 1 where id = se;
  exception when others then ok_u := true; end;
  begin delete from sales_entries where id = se;
  exception when others then ok_d := true; end;

  perform c('0014','T36 recorded sales_entry cannot be UPDATEd or DELETEd', ok_u and ok_d);

  res := fn_void_sales_entry(se, 'miscount at close of day');
  perform c('0014','T36b sales_entry void path works and is auditable',
    (res->>'voided')::boolean
      and exists(select 1 from v_voided_sales where record_id = se));
end $$;

-- TEST 35: the Gate 1 R5 property must survive. A sales user records and
-- finalises a sale, the cost freezes correctly, and that user still cannot
-- read a single cost figure.
do $$
declare
  f record; g record; su uuid; ord2 uuid; froze numeric; saw_cost int; ok_fin boolean;
begin
  select * into f from _cfx; select * into g from _cfx2;
  insert into auth.users (id,email) values (gen_random_uuid(),'salesperson@test.local') returning id into su;
  insert into memberships (account_id,business_id,user_id,role) values (f.acc,null,su,'sales');

  set local role authenticated;
  perform set_config('request.jwt.claim.sub', su::text, true);

  insert into orders (account_id,business_id,order_no,order_date)
  values (f.acc,f.biz,'A2-SALES',current_date) returning id into ord2;
  insert into order_lines (account_id,order_id,recipe_id,qty,unit_price)
  values (f.acc,ord2,g.rid,1,3500);
  ok_fin := (fn_finalise_order(ord2)->>'finalised')::boolean;
  select count(*) into saw_cost from cost_snapshots;      -- RLS must hide these

  reset role;
  perform set_config('request.jwt.claim.sub','',true);

  select unit_cost_at_sale into froze from order_lines where order_id = ord2;

  perform c('0014','T35 sales role finalises a sale, cost freezes, cost stays invisible',
    ok_fin and froze is not null and saw_cost = 0,
    format('finalised=%s frozen_cost=%s snapshots_visible_to_sales=%s', ok_fin, froze, saw_cost));
end $$;

-- ============================================================================
-- RESULTS
-- ============================================================================
select seq, phase, case when passed then 'PASS' else 'FAIL' end as result, name from _c1 order by seq;
select count(*) filter (where passed) as passed,
       count(*) filter (where not passed) as failed,
       count(*) as total
from _c1;
